export const STANDARD_VERTEX_SHADER: "#version 300 es\n  layout(location = 0) in vec4 aVertexPosition;\n  layout(location = 1) in vec2 aTextureCoord;\n\n  layout(location = 2) in vec4 aInstanceMatrix0;\n  layout(location = 3) in vec4 aInstanceMatrix1;\n  layout(location = 4) in vec4 aInstanceMatrix2;\n  layout(location = 5) in vec4 aInstanceMatrix3;\n\n  layout(location = 6) in vec2 aInstanceTexCoord0;\n  layout(location = 7) in vec2 aInstanceTexCoord1;\n  layout(location = 8) in vec2 aInstanceTexCoord2;\n  layout(location = 9) in vec2 aInstanceTexCoord3;\n\n  layout(location = 10) in vec4 aInstanceColor;\n\n  uniform mat4 uModelViewMatrix;\n  uniform mat4 uInstancedModelViewMatrix;\n  uniform mat4 uProjectionMatrix;\n  uniform bool useInstances;\n\n  centroid out highp vec2 vTexCoord;\n  out vec2 vFragPos;\n  out vec4 vInstanceColor;\n\n  void main() {\n    mat4 instanceMatrix = mat4(\n      aInstanceMatrix0,\n      aInstanceMatrix1,\n      aInstanceMatrix2,\n      aInstanceMatrix3\n    );\n\n    if(useInstances) {\n        gl_Position = uProjectionMatrix * uInstancedModelViewMatrix * instanceMatrix * aVertexPosition;\n        vFragPos = (uInstancedModelViewMatrix * instanceMatrix * aVertexPosition).xy;\n        vInstanceColor = aInstanceColor;\n\n        int vertexIndex = aVertexPosition.x > 0.0 ? (aVertexPosition.y > 0.0 ? 0 : 2) : (aVertexPosition.y > 0.0 ? 1 : 3);\n\n        if(vertexIndex == 0) {\n            vTexCoord = aInstanceTexCoord0;\n        } else if(vertexIndex == 1) {\n            vTexCoord = aInstanceTexCoord1;\n        } else if(vertexIndex == 2) {\n            vTexCoord = aInstanceTexCoord2;\n        } else {\n            vTexCoord = aInstanceTexCoord3;\n        }\n    } else {\n        gl_Position = uProjectionMatrix * uModelViewMatrix * aVertexPosition;\n        vFragPos = (uModelViewMatrix * aVertexPosition).xy;\n        vTexCoord = aTextureCoord;\n        vInstanceColor = vec4(1.0);\n    }\n  }\n";
export const STANDARD_FRAGMENT_SHADER: "#version 300 es\n    precision highp float;\n    uniform bool useTexture;\n    uniform vec4 uColor;\n    uniform sampler2D uSampler;\n    uniform float uOpacity;\n\n    uniform vec2 uLightPosition[4];\n    uniform vec3 uLightColor[4];\n    uniform float uLightIntensity[4];\n    uniform float uLightRadius[4];\n    uniform int uActiveLights;\n\n    uniform vec2 uDirLightPosition[4];\n    uniform vec2 uDirLightDirection[4];\n    uniform vec3 uDirLightColor[4];\n    uniform float uDirLightIntensity[4];\n    uniform float uDirLightWidth[4];\n    uniform int uActiveDirLights;\n\n    uniform vec3 uAmbientLightValues;\n    uniform bool uUseLighting;\n\n    centroid in highp vec2 vTexCoord;\n    in vec2 vFragPos;\n    in vec4 vInstanceColor;\n\n    out vec4 fragColor;\n\n    void main() {\n        vec4 ambientLight = vec4(uAmbientLightValues.xyz, 1.0);\n\n        vec4 texColor;\n        if (useTexture) {\n            texColor = texture(uSampler, vTexCoord);\n            if (texColor.a < 0.01) discard;\n            texColor *= uColor;\n        } else {\n            texColor = uColor;\n        }\n\n        texColor *= vInstanceColor;\n\n        vec3 lighting = ambientLight.rgb;\n\n        for(int i = 0; i < 4; i++) {\n            if(i >= uActiveLights) break;\n\n            float distance = length(uLightPosition[i] - vFragPos);\n\n            if(distance < uLightRadius[i]) {\n                float attenuation = 1.0 - distance / uLightRadius[i];\n\n                lighting += uLightColor[i] * attenuation * uLightIntensity[i];\n            }\n        }\n\n        for(int i = 0; i < 4; i++) {\n            if(i >= uActiveDirLights) break;\n\n            vec2 lightPos = uDirLightPosition[i];\n            vec2 lightDir = normalize(uDirLightDirection[i]);\n            vec2 toFrag = vFragPos - lightPos;\n\n            float projection = dot(toFrag, lightDir);\n            if(projection < 0.0) continue;\n\n            float perpDistance = abs(dot(toFrag, vec2(-lightDir.y, lightDir.x)));\n\n            if(perpDistance > uDirLightWidth[i] * 0.5) continue;\n\n            float widthFactor = 1.0 - (perpDistance / (uDirLightWidth[i] * 0.5));\n\n            float distance = length(toFrag);\n            float maxDistance = 1000.0;\n            float distanceFactor = max(0.0, 1.0 - (distance / maxDistance));\n\n            lighting += uDirLightColor[i] * uDirLightIntensity[i] * widthFactor * distanceFactor;\n        }\n\n        vec4 outColor;\n        if (uUseLighting) {\n            outColor = vec4(texColor.rgb * lighting, texColor.a);\n        } else {\n            outColor = texColor;\n        }\n        outColor.a *= clamp(uOpacity, 0.0, 1.0);\n        fragColor = outColor;\n    }\n";
export const LEGACY_VERTEX_PRELUDE: "\n#define attribute in\n#define varying out\n";
export const LEGACY_FRAGMENT_PRELUDE: "\n#define varying in\n#define texture2D texture\n#define texture2DProj textureProj\n#define texture2DLod textureLod\n#define texture2DLodEXT textureLod\n#define gl_FragColor fragColor\n";
/**
 * @method adaptLegacyGLSL
 * @description Lets user-written GLSL ES 1.00 sources (Material fragment and
 * vertex bodies, PostEffect fragments) run under the engine's GLSL ES 3.00
 * headers. The preludes above map `attribute`, `varying`, `texture2D` and
 * `gl_FragColor` onto their ES 3.00 forms; this strips the `#extension` lines
 * for features that are built into ES 3.00 and would otherwise fail to compile.
 * @param {string} source - Shader body written against ES 1.00 or ES 3.00
 * @returns {string} - The body, safe to append after an engine header
 */
export function adaptLegacyGLSL(source: string): string;
